  const [empModalNotificationTiming, setEmpModalNotificationTiming] = useState<'immediately' | '24h_before' | '1w_before'>('immediately');
  const [empModalEmployeeVisibility, setEmpModalEmployeeVisibility] = useState<'published_all' | 'published_weekly' | 'draft'>('published_all');
  const [shiftMatrixSearch, setShiftMatrixSearch] = useState('');
  const [shiftMatrixFilterField, setShiftMatrixFilterField] = useState<'all' | 'name' | 'department' | 'team' | 'job_title'>('all');
  const [selectedForecastDay, setSelectedForecastDay] = useState<{ dayIdx: number; nameEn: string; dateStr: string; displayDate: string } | null>(null);
  const [matrixSelectedDate, setMatrixSelectedDate] = useState<Date>(() => new Date());

  const matrixWeekDates = useMemo(() => {
    const current = new Date(matrixSelectedDate);
    const day = current.getDay(); // 0 is Sunday
    const sunday = new Date(current);
    sunday.setDate(current.getDate() - day);

    const dates: { dayIdx: number; nameEn: string; dateStr: string; displayDate: string; isToday: boolean }[] = [];
    const dayNames = ['SUN', 'MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT'];
    const todayStr = new Date().toISOString().split('T')[0];

    for (let i = 0; i < 7; i++) {
      const d = new Date(sunday);
      d.setDate(sunday.getDate() + i);
      const dateStr = d.toISOString().split('T')[0];
      const monthName = d.toLocaleString('en-US', { month: 'short' });
      const dayNum = d.getDate();
      dates.push({
        dayIdx: i,
        nameEn: dayNames[i],
        dateStr,
        displayDate: `${monthName} ${dayNum}`,
        isToday: dateStr === todayStr
      });
    }

    const weekStartStr = dates[0].displayDate;
    const weekEndStr = dates[6].displayDate;
    const yearStr = sunday.getFullYear();

    return {
      sunday,
      dates,
      startDate: dates[0].dateStr,
      endDate: dates[6].dateStr,
      weekRangeLabel: `${weekStartStr} - ${weekEndStr}, ${yearStr}`
    };
  }, [matrixSelectedDate]);

  // Eligible employees for the matrix in the currently viewed week:
  // 1. All active employees
  // 2. Inactive employees ONLY if they have shift assignments, attendance logs, or approved leaves in this viewed week (historical preservation)
  const eligibleMatrixEmployees = useMemo(() => {
    return employees.filter(emp => {
      const isInactive = ['inactive', 'terminated', 'archived', 'disabled', 'deleted', 'suspended'].includes(
        (emp.status || '').toLowerCase()
      );

      if (!isInactive) return true;

      const empUserId = emp.user_id ? Number(emp.user_id) : null;
      const empId = Number(emp.id);

      // Check shift assignments in the viewed week
      const hasShiftInWeek = shiftAssignments.some(sa => {
        const isMatch = Number(sa.user_id) === empId || (empUserId !== null && Number(sa.user_id) === empUserId);
        if (!isMatch) return false;

        if (sa.start_date && sa.end_date) {
          return !(sa.end_date < matrixWeekDates.startDate || sa.start_date > matrixWeekDates.endDate);
        }
        if (sa.start_date && !sa.end_date) {
          return sa.start_date >= matrixWeekDates.startDate && sa.start_date <= matrixWeekDates.endDate;
        }
        return false;
      });
      if (hasShiftInWeek) return true;

      // Check attendance logs in the viewed week
      const hasAttendanceInWeek = attendance.some(a => {
        const isMatch = Number(a.user_id) === empId || Number((a as any).employee_id) === empId || (empUserId !== null && Number(a.user_id) === empUserId);
        if (!isMatch || !a.date) return false;
        const aDate = String(a.date).split('T')[0].split(' ')[0];
        return aDate >= matrixWeekDates.startDate && aDate <= matrixWeekDates.endDate;
      });
      if (hasAttendanceInWeek) return true;

      // Check approved leaves in the viewed week
      const hasLeaveInWeek = leaves.some(l => {
        const isMatch = Number(l.user_id) === empId || (empUserId !== null && Number(l.user_id) === empUserId);
        if (!isMatch || l.status !== 'Approved' || !l.start_date || !l.end_date) return false;
        const lStart = String(l.start_date).split('T')[0];
        const lEnd = String(l.end_date).split('T')[0];
        return !(lEnd < matrixWeekDates.startDate || lStart > matrixWeekDates.endDate);
      });
      if (hasLeaveInWeek) return true;

      return false;
    });
  }, [employees, shiftAssignments, attendance, leaves, matrixWeekDates]);

  const matrixFieldOptions = useMemo(() => {
    if (shiftMatrixFilterField === 'name') {
      return Array.from(new Set(eligibleMatrixEmployees.map(e => e.name).filter(Boolean))).sort();
    }
    if (shiftMatrixFilterField === 'department') {
      const deptNames = departments.map(d => d.name).filter(Boolean);
      const empDepts = eligibleMatrixEmployees.map(e => departments.find(d => d.id === e.department_id)?.name).filter(Boolean) as string[];
      return Array.from(new Set([...deptNames, ...empDepts])).sort();
    }
    if (shiftMatrixFilterField === 'team') {
      return Array.from(new Set(eligibleMatrixEmployees.map(e => e.team_name).filter(Boolean) as string[])).sort();
    }
    if (shiftMatrixFilterField === 'job_title') {
      return Array.from(new Set(eligibleMatrixEmployees.map(e => e.job_title).filter(Boolean) as string[])).sort();
    }
    // 'all'
    const names = eligibleMatrixEmployees.map(e => e.name).filter(Boolean);
    const depts = departments.map(d => d.name).filter(Boolean);
    const teams = eligibleMatrixEmployees.map(e => e.team_name).filter(Boolean) as string[];
    const titles = eligibleMatrixEmployees.map(e => e.job_title).filter(Boolean) as string[];
    return Array.from(new Set([...names, ...depts, ...teams, ...titles])).sort();
  }, [shiftMatrixFilterField, eligibleMatrixEmployees, departments]);

  // Company Holidays state synced with localStorage and custom event
  const [companyHolidays, setCompanyHolidays] = useState<CompanyHoliday[]>(() => {
    try {
      const saved = localStorage.getItem('hr_company_holidays');
      if (saved) {
        const parsed = JSON.parse(saved);
        if (Array.isArray(parsed) && parsed.length > 0) return parsed;
      }
    } catch (e) {
      console.error('Failed to parse company holidays in HRManagement:', e);
    }
    return DEFAULT_HOLIDAYS;
  });

  useEffect(() => {
    const handleHolidaysUpdate = () => {
      try {
        const saved = localStorage.getItem('hr_company_holidays');
        if (saved) {
          const parsed = JSON.parse(saved);
          if (Array.isArray(parsed) && parsed.length > 0) {
            setCompanyHolidays(parsed);
            return;
          }
        }
      } catch (e) {}
      setCompanyHolidays(DEFAULT_HOLIDAYS);
    };

    window.addEventListener('company_holidays_updated', handleHolidaysUpdate);
    window.addEventListener('storage', handleHolidaysUpdate);
    return () => {
      window.removeEventListener('company_holidays_updated', handleHolidaysUpdate);
      window.removeEventListener('storage', handleHolidaysUpdate);
    };
  }, []);

  // Quick Action Modal for Matrix Empty / Slot Click
