  const [matrixActionTargetEmp, setMatrixActionTargetEmp] = useState<Employee | null>(null);
  const [matrixActionTargetDay, setMatrixActionTargetDay] = useState<{
    dayIdx: number;
    nameEn: string;
    dateStr: string;
    displayDate: string;
    isToday: boolean;
  } | null>(null);

  // Helper to match company holiday for a date and employee department
  const getCompanyHolidayForDate = useCallback((dateStr: string, empDepartmentId?: number | null): CompanyHoliday | null => {
    if (!dateStr || !companyHolidays.length) return null;
    const targetMonthDay = dateStr.slice(5); // 'MM-DD'

    for (const hol of companyHolidays) {
      // Check department scope if restricted
      if (hol.departmentScope && hol.departmentScope !== 'All' && Array.isArray(hol.departmentScope)) {
        if (!empDepartmentId || !hol.departmentScope.includes(Number(empDepartmentId))) {
          continue;
        }
      }

      const start = hol.startDate;
      const end = hol.endDate || hol.startDate;

      if (hol.isRecurringYearly) {
        const startMD = start.slice(5);
        const endMD = end.slice(5);
        if (startMD === endMD) {
          if (targetMonthDay === startMD) return hol;
        } else if (startMD <= endMD) {
          if (targetMonthDay >= startMD && targetMonthDay <= endMD) return hol;
        } else {
          if (targetMonthDay >= startMD || targetMonthDay <= endMD) return hol;
        }
      } else {
        if (dateStr >= start && dateStr <= end) {
          return hol;
        }
      }
    }
    return null;
  }, [companyHolidays]);

  // Handler for quick shift save from matrix cell
  const handleMatrixQuickSaveShift = async (data: {
    employeeId: number;
    shiftId: number;
    dayIdx: number;
    dateStr: string;
    scope: 'date_only' | 'week' | 'recurring';
    startDate?: string;
    endDate?: string;
    startTime?: string;
    endTime?: string;
  }) => {
    const targetEmp = employees.find(e => e.id === data.employeeId);
    const empUserId = targetEmp?.user_id || data.employeeId;
    const effectiveStartDate = data.scope === 'recurring' ? undefined : (data.startDate || data.dateStr);
    const effectiveEndDate = data.scope === 'recurring' ? undefined : (data.endDate || data.dateStr);
    const effectiveRecurrence = data.scope === 'recurring' ? 'weekly' : 'none';

    try {
      const res = await fetch('/api/hr/shift-assignments', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'x-user-id': currentUser?.id?.toString() || '1'
        },
        body: JSON.stringify({
          user_ids: [empUserId],
          days_of_week: [data.dayIdx],
          clearExisting: data.scope === 'date_only',
          startDate: effectiveStartDate,
          endDate: effectiveEndDate,
          recurrence: effectiveRecurrence,
          is_published: true,
          employee_visibility: 'published_all',
          assignments: [
            {
              user_id: empUserId,
              shift_id: data.shiftId,
              day_of_week: data.dayIdx
            }
          ]
        })
      });

      if (res.ok) {
        showCustomToast(`Shift assigned successfully for ${targetEmp?.name || 'employee'}!`, 'success');
        await fetchData();
      } else {
        showCustomToast('Failed to assign shift', 'error');
      }
    } catch (err) {
      console.error(err);
      showCustomToast('Network error while assigning shift', 'error');
    }
  };

  // Handler for quick holiday save from matrix cell
  const handleMatrixQuickSaveHoliday = async (data: {
    employeeId: number;
    holidayName: string;
    holidayType: 'National' | 'Religious' | 'Company' | 'Observance';
    isPaid: boolean;
    dateStr: string;
    scope: 'all' | 'department' | 'employee_only';
    color: string;
  }) => {
    const targetEmp = employees.find(e => e.id === data.employeeId);
    const empUserId = targetEmp?.user_id || data.employeeId;

    // 1. Update company holidays list if new or update scope
    const existingIndex = companyHolidays.findIndex(h => h.name.toLowerCase() === data.holidayName.toLowerCase() && h.startDate === data.dateStr);
    let updatedList = [...companyHolidays];
    if (existingIndex === -1) {
      const newHol: CompanyHoliday = {
        id: `hol-${Date.now()}`,
        name: data.holidayName,
        startDate: data.dateStr,
        endDate: data.dateStr,
        type: data.holidayType,
        isPaid: data.isPaid,
        isRecurringYearly: false,
        departmentScope: data.scope === 'department' && targetEmp?.department_id ? [targetEmp.department_id] : 'All',
        color: data.color
      };
      updatedList = [newHol, ...updatedList];
      setCompanyHolidays(updatedList);
      try {
        localStorage.setItem('hr_company_holidays', JSON.stringify(updatedList));
        window.dispatchEvent(new Event('company_holidays_updated'));
      } catch (e) {}
    }

    // 2. Also register a shift assignment with shift_id: -1 (Public Holiday) so it persists in the schedule
    try {
      const targetUserIds = data.scope === 'all'
        ? eligibleMatrixEmployees.map(e => e.user_id || e.id)
        : data.scope === 'department'
        ? eligibleMatrixEmployees.filter(e => e.department_id === targetEmp?.department_id).map(e => e.user_id || e.id)
        : [empUserId];

      const dayIdx = new Date(data.dateStr + 'T00:00:00').getDay();

      await fetch('/api/hr/shift-assignments', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'x-user-id': currentUser?.id?.toString() || '1'
        },
        body: JSON.stringify({
          user_ids: targetUserIds,
          days_of_week: [dayIdx],
          startDate: data.dateStr,
          endDate: data.dateStr,
          recurrence: 'none',
          is_published: true,
          employee_visibility: 'published_all',
          assignments: targetUserIds.map(uid => ({
            user_id: uid,
            shift_id: -1,
            shift_name: data.holidayName,
            day_of_week: dayIdx
          }))
        })
      });

      showCustomToast(`Holiday "${data.holidayName}" applied to schedule matrix!`, 'success');
      await fetchData();
    } catch (err) {
      console.error(err);
      showCustomToast(`Holiday "${data.holidayName}" applied!`, 'success');
    }
  };

