const getSeniorityScore = (jobTitle: string = ''): number => {
  const t = (jobTitle || '').toLowerCase().trim();
  if (!t) return 999;
  
  if (t.includes('chief') || t.includes('ceo') || t.includes('cto') || t.includes('cfo') || t.includes('coo') || t.includes('president') || t.includes('رئيس') || t.includes('تنفيذي عام')) return 10;
  if (t.includes('vice president') || t.includes('vp') || t.includes('نائب')) return 20;
  if (t.includes('director') || t.includes('مواجه') || t.includes('مدير عام') || t.includes('مدير تنفيذي')) return 30;
  if (t.includes('head') || t.includes('رئيس قسم') || t.includes('قسم')) return 35;
  if (t.includes('manager') || t.includes('مدير')) return 40;
  if (t.includes('lead') || t.includes('قائد') || t.includes('مشرف') || t.includes('supervisor')) return 50;
  if (t.includes('senior') || t.includes('أول') || t.includes('كبير')) return 60;
  if (t.includes('specialist') || t.includes('مختص') || t.includes('أخصائي') || t.includes('استشاري') || t.includes('consultant')) return 70;
  if (t.includes('officer') || t.includes('ضابط') || t.includes('مسؤول') || t.includes('engineer') || t.includes('مهندس') || t.includes('analyst') || t.includes('محلل')) return 80;
  if (t.includes('executive') || t.includes('تنفيذي') || t.includes('coordinator') || t.includes('منسق') || t.includes('associate') || t.includes('مساعد') || t.includes('assistant')) return 90;
  if (t.includes('representative') || t.includes('ممثل') || t.includes('runner') || t.includes('مندوب') || t.includes('عامل') || t.includes('سائق')) return 100;
  
  return 110;
};

const getJobTitleGradeRank = (jobTitle: string = '', deptObj?: any): number => {
  const t = (jobTitle || '').toLowerCase().trim();
  if (!t) return 999;

  // 1. Check department job_titles array for level/grade
  if (deptObj) {
    let rawTitles: any[] = [];
    if (Array.isArray(deptObj.job_titles)) rawTitles = deptObj.job_titles;
    else if (typeof deptObj.job_titles === 'string') {
      try { rawTitles = JSON.parse(deptObj.job_titles); } catch (e) {}
    }

    const foundItem = rawTitles.find((jt: any) => {
      const s = typeof jt === 'string' ? jt : (jt?.title || jt?.name || '');
      return (s || '').toLowerCase().trim() === t;
    });

    if (foundItem && typeof foundItem === 'object' && foundItem.level) {
      const levelStr = String(foundItem.level).toLowerCase();
      const match = levelStr.match(/grade\s*(\d+)/i) || levelStr.match(/level\s*(\d+)/i) || levelStr.match(/(\d+)/);
      if (match) return parseInt(match[1], 10);
      if (levelStr.includes('executive') || levelStr.includes('c-level') || levelStr.includes('grade 1')) return 1;
      if (levelStr.includes('director') || levelStr.includes('vp') || levelStr.includes('grade 2')) return 2;
      if (levelStr.includes('head') || levelStr.includes('manager') || levelStr.includes('grade 3')) return 3;
      if (levelStr.includes('lead') || levelStr.includes('senior') || levelStr.includes('grade 4')) return 4;
      if (levelStr.includes('specialist') || levelStr.includes('mid') || levelStr.includes('grade 5')) return 5;
      if (levelStr.includes('junior') || levelStr.includes('associate') || levelStr.includes('grade 6')) return 6;
      if (levelStr.includes('intern') || levelStr.includes('trainee') || levelStr.includes('entry') || levelStr.includes('grade 7')) return 7;
    }
  }

  // 2. Check local or default job descriptions
  const defaultJd = (typeof DEFAULT_JOB_DESCRIPTIONS !== 'undefined' && DEFAULT_JOB_DESCRIPTIONS) 
    ? (DEFAULT_JOB_DESCRIPTIONS[jobTitle] || DEFAULT_JOB_DESCRIPTIONS[t]) 
    : null;
  if (defaultJd && defaultJd.grade) {
    const gStr = (defaultJd.grade || '').toLowerCase();
    const match = gStr.match(/grade\s*(\d+)/i) || gStr.match(/(\d+)/);
    if (match) return parseInt(match[1], 10);
  }

  // 3. Fallback keywords
  if (t.includes('chief') || t.includes('ceo') || t.includes('cto') || t.includes('cfo') || t.includes('coo') || t.includes('president') || t.includes('رئيس تنفيذي')) return 1;
  if (t.includes('vice president') || t.includes('vp') || t.includes('director') || t.includes('نائب') || t.includes('مدير عام')) return 2;
  if (t.includes('head') || t.includes('manager') || t.includes('مدير') || t.includes('رئيس قسم')) return 3;
  if (t.includes('lead') || t.includes('supervisor') || t.includes('قائد') || t.includes('مشرف') || t.includes('senior') || t.includes('كبير')) return 4;
  if (t.includes('specialist') || t.includes('أخصائي') || t.includes('مختص') || t.includes('engineer') || t.includes('مهندس') || t.includes('analyst')) return 5;
  if (t.includes('officer') || t.includes('junior') || t.includes('associate') || t.includes('مساعد') || t.includes('منسق')) return 6;
  if (t.includes('intern') || t.includes('trainee') || t.includes('متدرب') || t.includes('مندوب') || t.includes('عامل') || t.includes('سائق')) return 7;

  return 8;
};

  const operationalDepartments = useMemo(() => {
    return departments.filter((dept: any) => {
      if (dept.is_executive) return false;
      const deptNameLower = (dept.name || '').toLowerCase().trim();
      return !deptNameLower.includes('executive leadership') && 
             !deptNameLower.includes('board of directors') && 
             !deptNameLower.includes('إدارة تنفيذية') && 
             !deptNameLower.includes('مجلس إدارة') &&
             !deptNameLower.includes('قسم قيادي');
    });
  }, [departments]);

  const deptHierarchies = useMemo(() => {
    return operationalDepartments.map((dept: any) => {
      const deptEmployees = activeEmployees.filter(e => e.department_id === dept.id);

      // Extract configured job titles order from dept.job_titles
      let rawDeptTitles: any[] = [];
      if (Array.isArray(dept.job_titles)) rawDeptTitles = dept.job_titles;
      else if (typeof dept.job_titles === 'string') {
        try { rawDeptTitles = JSON.parse(dept.job_titles); } catch (e) {}
      }

      const configuredTitlesOrder: string[] = [];
      rawDeptTitles.forEach(jt => {
        const s = typeof jt === 'string' ? jt : (jt?.title || jt?.name);
        if (s && s.trim()) configuredTitlesOrder.push(s.trim());
      });

      const sortTitlesByConfig = (titleList: string[]) => {
        const normConfig = configuredTitlesOrder.map(t => (t || '').toLowerCase().trim());
        return [...titleList].sort((a, b) => {
          const rankA = getJobTitleGradeRank(a, dept);
          const rankB = getJobTitleGradeRank(b, dept);
          if (rankA !== rankB) return rankA - rankB;

          const normA = (a || '').toLowerCase().trim();
          const normB = (b || '').toLowerCase().trim();

          const idxA = normConfig.indexOf(normA);
          const idxB = normConfig.indexOf(normB);

          if (idxA !== -1 && idxB !== -1) return idxA - idxB;
          if (idxA !== -1) return -1;
          if (idxB !== -1) return 1;

          return getSeniorityScore(a) - getSeniorityScore(b);
        });
      };

      // Check if department has actual teams defined
      let rawTeams: any[] = [];
      if (Array.isArray(dept.teams)) rawTeams = dept.teams;
      else if (typeof dept.teams === 'string') {
        try { rawTeams = JSON.parse(dept.teams); } catch (e) {}
      }

      const teamNamesSet = new Set<string>();
      rawTeams.forEach(t => {
        const tName = typeof t === 'string' ? t : t?.name;
        if (tName && tName.trim()) teamNamesSet.add(tName.trim());
      });

      deptEmployees.forEach(e => {
        const tName = e.team_name || e.personal_info?.team_name;
        if (tName && tName.trim()) teamNamesSet.add(tName.trim());
      });

      const hasTeams = teamNamesSet.size > 0;

      if (hasTeams) {
        // Build Teams -> Job Titles
        const teamNames = Array.from(teamNamesSet);

        const teamsData = teamNames.map(tName => {
          const teamEmps = deptEmployees.filter(e => {
            const empTeam = (e.team_name || e.personal_info?.team_name || '').trim();
            if (teamNames.length === 1) return true;
            return empTeam === tName;
          });

          // Determine Job Titles for this team
          const titleNamesSet = new Set<string>();
          configuredTitlesOrder.forEach(t => titleNamesSet.add(t));

          teamEmps.forEach(e => {
            if (e.job_title && e.job_title.trim()) titleNamesSet.add(e.job_title.trim());
          });

          if (titleNamesSet.size === 0) {
            titleNamesSet.add('Team Member');
          }

          const titleNames = sortTitlesByConfig(Array.from(titleNamesSet));

          const titlesData = titleNames.map(titleName => {
            const titleEmps = teamEmps.filter(e => {
              const empTitle = (e.job_title || 'Team Member').trim();
              if (titleNames.length === 1) return true;
              return empTitle === titleName || (!titleNamesSet.has(empTitle) && titleName === 'Team Member');
            });

            return {
              name: titleName,
              employees: titleEmps,
              width: 220,
            };
          });

          const teamWidth = 240;

          return {
            name: tName,
            titles: titlesData,
            width: teamWidth,
            totalEmps: teamEmps.length
          };
        });

        const deptWidth = Math.max(260, teamsData.length * 260);

        return {
          dept,
          hasTeams: true,
          teams: teamsData,
          titles: [],
          width: deptWidth,
          totalEmps: deptEmployees.length
        };
      } else {
        // Direct Department -> Job Titles (NO TEAMS)
        const titleNamesSet = new Set<string>();
        configuredTitlesOrder.forEach(t => titleNamesSet.add(t));

        deptEmployees.forEach(e => {
          if (e.job_title && e.job_title.trim()) titleNamesSet.add(e.job_title.trim());
        });

        if (titleNamesSet.size === 0) {
          titleNamesSet.add('Department Staff');
        }

        const titleNames = sortTitlesByConfig(Array.from(titleNamesSet));

        const titlesData = titleNames.map(titleName => {
          const titleEmps = deptEmployees.filter(e => {
            const empTitle = (e.job_title || 'Department Staff').trim();
            if (titleNames.length === 1) return true;
            return empTitle === titleName || (!titleNamesSet.has(empTitle) && titleName === 'Department Staff');
          });

          return {
            name: titleName,
            employees: titleEmps,
            width: 220,
          };
        });

        const deptWidth = 260;

        return {
          dept,
          hasTeams: false,
          teams: [],
          titles: titlesData,
          width: deptWidth,
          totalEmps: deptEmployees.length
        };
      }
    });
  }, [operationalDepartments, activeEmployees]);

  const deptRoleHierarchies = useMemo(() => {
    return operationalDepartments.map((dept: any) => {
      const deptEmployees = activeEmployees.filter(e => e.department_id === dept.id);

      // 1. Identify Department Head
      let deptHead = dept.department_head_id 
        ? deptEmployees.find(e => String(e.id) === String(dept.department_head_id)) 
        : null;

      if (!deptHead && deptEmployees.length > 0) {
        deptHead = deptEmployees.find(e => {
          const jt = (e.job_title || '').toLowerCase();
          return jt.includes('head') || jt.includes('director') || jt.includes('manager') || jt.includes('رئيس') || jt.includes('مدير');
        }) || deptEmployees.slice().sort((a, b) => getSeniorityScore(a.job_title) - getSeniorityScore(b.job_title))[0];
      }

      // 2. Identify Team Leads (excluding Dept Head)
      const teamLeads = deptEmployees.filter(e => {
        if (deptHead && String(e.id) === String(deptHead.id)) return false;
        const jt = (e.job_title || '').toLowerCase();
        return jt.includes('lead') || jt.includes('supervisor') || jt.includes('قائد') || jt.includes('مشرف');
      }).sort((a, b) => getSeniorityScore(a.job_title) - getSeniorityScore(b.job_title));

      // 3. Staff employees (excluding Head and Leads)
      const leadIds = new Set(teamLeads.map(tl => String(tl.id)));
      const staffEmps = deptEmployees.filter(e => {
        if (deptHead && String(e.id) === String(deptHead.id)) return false;
        if (leadIds.has(String(e.id))) return false;
        return true;
      });

      // 4. Group staffEmps by job_title
      const titleGroupsMap = new Map<string, any[]>();
      staffEmps.forEach(e => {
        const title = (e.job_title || 'Staff Member').trim();
        if (!titleGroupsMap.has(title)) titleGroupsMap.set(title, []);
        titleGroupsMap.get(title)!.push(e);
      });

      const staffTitlesData = Array.from(titleGroupsMap.entries()).map(([titleName, emps]) => {
        const sortedEmps = emps.sort((a, b) => getSeniorityScore(a.job_title) - getSeniorityScore(b.job_title));
        const width = Math.max(220, sortedEmps.length * 220);
        return {
          name: titleName,
          employees: sortedEmps,
          width,
        };
      }).sort((a, b) => getSeniorityScore(a.name) - getSeniorityScore(b.name));

      const leadsWidth = Math.max(240, teamLeads.length * 230);
      const staffWidth = Math.max(240, staffTitlesData.reduce((acc, t) => acc + t.width, 0));
      const deptWidth = Math.max(280, deptHead ? 240 : 0, leadsWidth, staffWidth);

      return {
        dept,
        deptHead,
        teamLeads,
        staffTitles: staffTitlesData,
        width: deptWidth,
        totalEmps: deptEmployees.length
      };
    });
  }, [operationalDepartments, activeEmployees]);

  const generateHrOrgChart = useCallback(() => {
    const newNodes: Node[] = [];
    const newEdges: Edge[] = [];

    // 1. Executive Root Node at (0, 0)
    newNodes.push({
      id: 'exec-root',
      type: 'hrOrgExec',
      data: {
        title: 'Executive Leadership',
        subTitle: 'Board of Directors & CEO',
        user: topLeader,
        onSelectUser: (u: any) => u && setViewingEmployee(u)
      },
      position: { x: 0, y: 0 },
    });

    if (hierarchyMode === 'role') {
      const DEPT_GAP = 90;
      const totalWidth = deptRoleHierarchies.reduce((acc, d) => acc + d.width, 0) + Math.max(0, deptRoleHierarchies.length - 1) * DEPT_GAP;
      let currentDeptX = -totalWidth / 2;

      deptRoleHierarchies.forEach(drh => {
        const deptX = currentDeptX + drh.width / 2;
        currentDeptX += drh.width + DEPT_GAP;

        const deptNodeId = `dept-${drh.dept.id}`;

        // Level 1: Department Node
        newNodes.push({
          id: deptNodeId,
          type: 'hrOrgDept',
          data: {
            dept: drh.dept,
            name: drh.dept.name,
            memberCount: drh.totalEmps,
            onSelectDept: (deptObj: any) => setViewingDept(deptObj || drh.dept)
          },
          position: { x: deptX, y: 180 },
        });

        // Link Exec -> Dept
        newEdges.push({
          id: `e-exec-${deptNodeId}`,
          source: 'exec-root',
          target: deptNodeId,
          type: 'smoothstep',
          animated: true,
          style: { stroke: '#6366f1', strokeWidth: 2 },
          markerEnd: { type: MarkerType.ArrowClosed, color: '#6366f1' },
        });

        let parentForLeads = deptNodeId;
        let level2Y = 360;

        // Level 2: Department Head Node
        if (drh.deptHead) {
          const headNodeId = `head-${drh.dept.id}-${drh.deptHead.id}`;
          newNodes.push({
            id: headNodeId,
            type: 'hrOrgUser',
            data: {
              user: drh.deptHead,
              name: drh.deptHead.name,
              job_title: drh.deptHead.job_title || 'Department Head',
              departmentName: drh.dept.name,
              roleBadge: 'Department Head',
              onSelectUser: (u: any) => setViewingEmployee(u)
            },
            position: { x: deptX, y: 360 },
          });

          // Link Dept -> Head
          newEdges.push({
            id: `e-${deptNodeId}-${headNodeId}`,
            source: deptNodeId,
            target: headNodeId,
            type: 'smoothstep',
            animated: true,
            style: { stroke: '#f59e0b', strokeWidth: 2.5 },
            markerEnd: { type: MarkerType.ArrowClosed, color: '#f59e0b' },
          });

          parentForLeads = headNodeId;
          level2Y = 540;
        }

        let leadTargetIds: string[] = [];
        let level3Y = level2Y;

        // Level 3: Team Leads
        if (drh.teamLeads.length > 0) {
          const leadCount = drh.teamLeads.length;
          drh.teamLeads.forEach((tl, tlIdx) => {
            const tlX = leadCount > 1 
              ? deptX + (tlIdx - (leadCount - 1) / 2) * 230 
              : deptX;
            const tlNodeId = `lead-${drh.dept.id}-${tl.id}`;
            leadTargetIds.push(tlNodeId);

            newNodes.push({
              id: tlNodeId,
              type: 'hrOrgUser',
              data: {
                user: tl,
                name: tl.name,
                job_title: tl.job_title || 'Team Lead',
                departmentName: drh.dept.name,
                roleBadge: 'Team Lead',
                onSelectUser: (u: any) => setViewingEmployee(u)
              },
              position: { x: tlX, y: level3Y },
            });

            // Link Head/Dept -> Team Lead
            newEdges.push({
              id: `e-${parentForLeads}-${tlNodeId}`,
              source: parentForLeads,
              target: tlNodeId,
              type: 'smoothstep',
              animated: true,
              style: { stroke: '#8b5cf6', strokeWidth: 2 },
              markerEnd: { type: MarkerType.ArrowClosed, color: '#8b5cf6' },
            });
          });
        }

        const titleY = drh.teamLeads.length > 0 ? (level3Y + 180) : level2Y;
        const parentForTitles = leadTargetIds.length > 0 ? leadTargetIds[0] : parentForLeads;

        // Level 4: Staff Job Title Nodes & Employees
        let currentTitleX = deptX - drh.width / 2;
        drh.staffTitles.forEach((st) => {
          const titleX = currentTitleX + st.width / 2;
          currentTitleX += st.width;

          const titleNodeId = `role-title-${drh.dept.id}-${st.name.replace(/[^a-zA-Z0-9_-]/g, '_')}`;

          newNodes.push({
            id: titleNodeId,
            type: 'hrOrgTitle',
            data: {
              name: st.name,
              memberCount: st.employees.length,
            },
            position: { x: titleX, y: titleY },
          });

          // Link Parent -> Job Title
          newEdges.push({
            id: `e-${parentForTitles}-${titleNodeId}`,
            source: parentForTitles,
            target: titleNodeId,
            type: 'smoothstep',
            animated: true,
            style: { stroke: '#0d9488', strokeWidth: 2 },
            markerEnd: { type: MarkerType.ArrowClosed, color: '#0d9488' },
          });

          // Level 5: Employees under Job Title
          const empCount = st.employees.length;
          const empY = titleY + 180;
          st.employees.forEach((emp, empIdx) => {
            const empX = empCount > 1 
              ? titleX + (empIdx - (empCount - 1) / 2) * 220 
              : titleX;
            const empNodeId = `user-${emp.id}`;

            newNodes.push({
              id: empNodeId,
              type: 'hrOrgUser',
              data: {
                user: emp,
                name: emp.name,
                job_title: emp.job_title,
                departmentName: drh.dept.name,
                onSelectUser: (u: any) => setViewingEmployee(u)
              },
              position: { x: empX, y: empY },
            });

            // Link Job Title -> Employee
            newEdges.push({
              id: `e-${titleNodeId}-${empNodeId}`,
              source: titleNodeId,
              target: empNodeId,
              type: 'smoothstep',
              animated: true,
              style: { stroke: '#6366f1', strokeWidth: 1.5 },
              markerEnd: { type: MarkerType.ArrowClosed, color: '#6366f1' },
            });
          });
        });
      });
    } else {
      const DEPT_GAP = 80;
      const totalWidth = deptHierarchies.reduce((acc, d) => acc + d.width, 0) + Math.max(0, deptHierarchies.length - 1) * DEPT_GAP;
      let currentDeptX = -totalWidth / 2;

      deptHierarchies.forEach(dh => {
        const deptX = currentDeptX + dh.width / 2;
        currentDeptX += dh.width + DEPT_GAP;

        const deptNodeId = `dept-${dh.dept.id}`;

        // Level 1: Department Node at Y = 180
        newNodes.push({
          id: deptNodeId,
          type: 'hrOrgDept',
          data: {
            dept: dh.dept,
            name: dh.dept.name,
            memberCount: dh.totalEmps,
            onSelectDept: (deptObj: any) => setViewingDept(deptObj || dh.dept)
          },
          position: { x: deptX, y: 180 },
        });

        // Link Exec -> Dept
        newEdges.push({
          id: `e-exec-${deptNodeId}`,
          source: 'exec-root',
          target: deptNodeId,
          type: 'smoothstep',
          animated: true,
          style: { stroke: '#6366f1', strokeWidth: 2 },
          markerEnd: { type: MarkerType.ArrowClosed, color: '#6366f1' },
        });

        if (dh.hasTeams) {
          // Level 2: Teams under Department at Y = 360
          let currentTeamX = deptX - dh.width / 2;
          dh.teams.forEach(team => {
            const teamX = currentTeamX + team.width / 2;
            currentTeamX += team.width;

            const teamNodeId = `team-${dh.dept.id}-${team.name.replace(/[^a-zA-Z0-9_-]/g, '_')}`;

            newNodes.push({
              id: teamNodeId,
              type: 'hrOrgTeam',
              data: {
                name: team.name,
                memberCount: team.totalEmps,
              },
              position: { x: teamX, y: 360 },
            });

            // Link Dept -> Team
            newEdges.push({
              id: `e-${deptNodeId}-${teamNodeId}`,
              source: deptNodeId,
              target: teamNodeId,
              type: 'smoothstep',
              animated: true,
              style: { stroke: '#8b5cf6', strokeWidth: 2 },
              markerEnd: { type: MarkerType.ArrowClosed, color: '#8b5cf6' },
            });

            // Level 3+: Hierarchical Job Titles stacked vertically under Team
            // (Executive Grade 1 > Director Grade 2 > Manager Grade 3 > Senior Grade 4 > Junior Grade 5)
            let parentNodeId = teamNodeId;
            let currentTitleY = 520;

            team.titles.forEach(title => {
              const titleNodeId = `title-${dh.dept.id}-${team.name.replace(/[^a-zA-Z0-9_-]/g, '_')}-${title.name.replace(/[^a-zA-Z0-9_-]/g, '_')}`;

              newNodes.push({
                id: titleNodeId,
                type: 'hrOrgTitle',
                data: {
                  name: title.name,
                  memberCount: title.employees.length,
                },
                position: { x: teamX, y: currentTitleY },
              });

              // Link Parent (Team or upper Grade Job Title) -> Current Job Title
              newEdges.push({
                id: `e-${parentNodeId}-${titleNodeId}`,
                source: parentNodeId,
                target: titleNodeId,
                type: 'smoothstep',
                animated: true,
                style: { stroke: '#0d9488', strokeWidth: 2 },
                markerEnd: { type: MarkerType.ArrowClosed, color: '#0d9488' },
              });

              parentNodeId = titleNodeId;
              currentTitleY += 130;
            });
          });
        } else {
          // Direct Dept -> Hierarchical Job Titles stacked vertically at Y = 360, 490, 620... (No teams)
          let parentNodeId = deptNodeId;
          let currentTitleY = 360;

          dh.titles.forEach(title => {
            const titleNodeId = `title-${dh.dept.id}-${title.name.replace(/[^a-zA-Z0-9_-]/g, '_')}`;

            newNodes.push({
              id: titleNodeId,
              type: 'hrOrgTitle',
              data: {
                name: title.name,
                memberCount: title.employees.length,
              },
              position: { x: deptX, y: currentTitleY },
            });

            // Link Parent (Dept or upper Grade Job Title) -> Current Job Title
            newEdges.push({
              id: `e-${parentNodeId}-${titleNodeId}`,
              source: parentNodeId,
              target: titleNodeId,
              type: 'smoothstep',
              animated: true,
              style: { stroke: '#0d9488', strokeWidth: 2 },
              markerEnd: { type: MarkerType.ArrowClosed, color: '#0d9488' },
            });

            parentNodeId = titleNodeId;
            currentTitleY += 130;
          });
        }
      });
    }

    setNodes(newNodes);
    setEdges(newEdges);
  }, [topLeader, deptHierarchies, deptRoleHierarchies, hierarchyMode, setNodes, setEdges]);

  useEffect(() => {
    if (activeTab === 'orgchart') {
      generateHrOrgChart();
    }
  }, [activeTab, generateHrOrgChart]);
  const [showShiftModal, setShowShiftModal] = useState(false);
  const [showAssignModal, setShowAssignModal] = useState(false);
  const [showScheduleBreakModal, setShowScheduleBreakModal] = useState(false);
  const [showPerformanceModal, setShowPerformanceModal] = useState(false);
  const [performanceAnalysis, setPerformanceAnalysis] = useState<any>(null);
  const [analyzedEmployee, setAnalyzedEmployee] = useState<Employee | null>(null);
  const [analysisStartDate, setAnalysisStartDate] = useState(
    new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString().split('T')[0]
  );
  const [analysisEndDate, setAnalysisEndDate] = useState(
    new Date().toISOString().split('T')[0]
  );
  const [isRefreshingAnalysis, setIsRefreshingAnalysis] = useState(false);

  const calculateCommissionForEmployee = useCallback((employeeId: number, wonCount: number, wonValue: number) => {
    let settings = {
      activeScheme: 'revenue_fixed',
      profitCostPercentage: 15,
      revenueFixedPercentage: 3.5,
      volumeCalculationType: 'flat',
      volumeTiers: [
        { min: 1, max: 5, rate: 250 },
        { min: 6, max: 15, rate: 450 },
        { min: 16, max: 999999, rate: 700 }
      ],
      revenueCalculationType: 'flat',
      revenueTiers: [
        { min: 1, max: 50000, rate: 2.0 },
        { min: 50001, max: 200000, rate: 4.5 },
        { min: 200001, max: 99999999, rate: 7.0 }
      ],
      repOverrides: {} as Record<number, { customCost?: number; customCostPercentage?: number }>
    };

    const saved = localStorage.getItem('crm_commission_settings');
    if (saved) {
      try {
        settings = JSON.parse(saved);
      } catch (e) {
        // ignore
      }
    }

    const { activeScheme } = settings;

    // Get overrides or default
    const repOverride = settings.repOverrides?.[employeeId] || {};
    const costPercentage = repOverride.customCostPercentage !== undefined ? repOverride.customCostPercentage : settings.profitCostPercentage;
    const totalCost = repOverride.customCost !== undefined ? repOverride.customCost : (wonValue * (costPercentage / 100));
    const netProfit = Math.max(0, wonValue - totalCost);

    let amount = 0;
    let description = '';
    let formula = '';
    let matchedTierName = 'N/A';

    switch (activeScheme) {
      case 'revenue_fixed': {
        const rate = settings.revenueFixedPercentage || 0;
        amount = wonValue * (rate / 100);
        formula = `${wonValue.toLocaleString()} × ${rate}%`;
        description = `Fixed percentage (${rate}%) of total revenue won.`;
        break;
      }
      case 'volume_tiers': {
        const tiers = [...settings.volumeTiers].sort((a, b) => a.min - b.min);
        const type = settings.volumeCalculationType;

        if (type === 'flat') {
          const matched = tiers.find(t => wonCount >= t.min && wonCount <= t.max) || 
                          tiers.filter(t => wonCount >= t.min).pop();
          const rate = matched ? matched.rate : 0;
          amount = wonCount * rate;
          matchedTierName = matched ? `Tier (${matched.min}-${matched.max === 999999 ? '∞' : matched.max})` : 'No Tier';
          formula = `${wonCount} orders × EGP ${rate}/order (Flat Tier Mode)`;
          description = matched ? `Flat tier payout of EGP ${rate} per order because orders count is in range [${matched.min} - ${matched.max === 999999 ? '∞' : matched.max}].` : 'No tier matched.';
        } else {
          // Cumulative
          let temp = wonCount;
          let calcSum = 0;
          let steps: string[] = [];
          tiers.forEach((t) => {
            if (wonCount >= t.min) {
              const countInTier = Math.min(wonCount, t.max) - (t.min - 1);
              if (countInTier > 0) {
                const tierPayout = countInTier * t.rate;
                calcSum += tierPayout;
                steps.push(`${countInTier} in Tier [${t.min}-${t.max === 999999 ? '∞' : t.max}] @ EGP ${t.rate}`);
              }
            }
          });
          amount = calcSum;
          formula = steps.join(' + ');
          description = `Cumulative payout calculated progressively across all tiers.`;
        }
        break;
      }
      case 'revenue_tiers': {
        const tiers = [...settings.revenueTiers].sort((a, b) => a.min - b.min);
        const type = settings.revenueCalculationType;

        if (type === 'flat') {
          const matched = tiers.find(t => wonValue >= t.min && wonValue <= t.max) || 
                          tiers.filter(t => wonValue >= t.min).pop();
          const rate = matched ? matched.rate : 0;
          amount = wonValue * (rate / 100);
          matchedTierName = matched ? `Tier (${matched.min.toLocaleString()}-${matched.max === 99999999 ? '∞' : matched.max.toLocaleString()})` : 'No Tier';
          formula = `${wonValue.toLocaleString()} × ${rate}% (Flat Tier Mode)`;
          description = matched ? `Flat percentage of ${rate}% because revenue is in range [EGP ${matched.min.toLocaleString()} - EGP ${matched.max === 99999999 ? '∞' : matched.max.toLocaleString()}].` : 'No tier matched.';
        } else {
          // Cumulative bands
          let calcSum = 0;
          let steps: string[] = [];
          tiers.forEach((t) => {
            const minPortion = Math.min(t.max, wonValue);
            const portion = Math.max(0, minPortion - t.min);
            if (portion > 0) {
              const tierPayout = portion * (t.rate / 100);
              calcSum += tierPayout;
              steps.push(`EGP ${portion.toLocaleString()} in Tier [${t.min.toLocaleString()}-${t.max === 99999999 ? '∞' : t.max.toLocaleString()}] @ ${t.rate}%`);
            }
          });
          amount = calcSum;
          formula = steps.join(' + ');
          description = `Cumulative percentage calculated progressively across all revenue bands.`;
        }
        break;
      }
      default:
        break;
    }

    return {
      amount,
      formula,
      description,
      wonCount,
      wonValue
    };
  }, []);

  // Live Performance & Filtering States
