  const handleDeleteShift = async (shiftId: number) => {
    if (!confirm('Are you sure you want to delete this shift?')) return;
    try {
      const res = await fetch(`/api/hr/shifts/${shiftId}`, { 
        method: 'DELETE',
        headers: {
          'x-user-id': currentUser?.id?.toString() || '1'
        }
      });
      if (res.ok) {
        showCustomToast('Shift deleted successfully', 'success');
        fetchData();
      } else {
        showCustomToast('Failed to delete shift', 'error');
      }
    } catch (err) {
      console.error('Failed to delete shift:', err);
      showCustomToast('Error deleting shift', 'error');
    }
  };

  const availableDepartments = useMemo(() => {
    const deptSet = new Set<string>();
    departments.forEach(d => { if (d.name) deptSet.add(d.name); });
    employees.forEach(e => { if (e.department_name) deptSet.add(e.department_name); });
    return Array.from(deptSet).sort();
  }, [departments, employees]);

  const shiftConflictStatus = useMemo(() => {
    const selectedShifts = shifts.filter(s => multiAssignmentForm.shift_ids.includes(s.id));
    if (selectedShifts.length <= 1) {
      return { hasConflict: false, message: 'No Conflicts Detected' };
    }

    const toMinutes = (timeStr: string) => {
      if (!timeStr) return 0;
      const parts = timeStr.split(':').map(Number);
      return (parts[0] || 0) * 60 + (parts[1] || 0);
    };

    for (let i = 0; i < selectedShifts.length; i++) {
      for (let j = i + 1; j < selectedShifts.length; j++) {
        const s1 = selectedShifts[i];
        const s2 = selectedShifts[j];
        const start1 = toMinutes(s1.start_time);
        const end1 = toMinutes(s1.end_time);
        const start2 = toMinutes(s2.start_time);
        const end2 = toMinutes(s2.end_time);

        if (start1 < end2 && start2 < end1) {
          return { 
            hasConflict: true, 
            message: `Overlap Conflict: "${s1.name}" (${s1.start_time.slice(0, 5)}-${s1.end_time.slice(0, 5)}) overlaps with "${s2.name}" (${s2.start_time.slice(0, 5)}-${s2.end_time.slice(0, 5)})` 
          };
        }
      }
    }

    return { hasConflict: false, message: 'No Conflicts Detected' };
  }, [shifts, multiAssignmentForm.shift_ids]);

