  const [directoryTeamFilter, setDirectoryTeamFilter] = useState<string | 'all'>('all');
  const [directoryJobTitleFilter, setDirectoryJobTitleFilter] = useState<string | 'all'>('all');

  const [leaveFilterDept, setLeaveFilterDept] = useState<number | 'all'>('all');
  const [leaveFilterTeam, setLeaveFilterTeam] = useState<string | 'all'>('all');
  const [leaveFilterJobTitle, setLeaveFilterJobTitle] = useState<string | 'all'>('all');

  const [shiftFilterDept, setShiftFilterDept] = useState<number | 'all'>('all');
  const [shiftFilterTeam, setShiftFilterTeam] = useState<string | 'all'>('all');
  const [shiftFilterJobTitle, setShiftFilterJobTitle] = useState<string | 'all'>('all');

  const [perfFilterTeam, setPerfFilterTeam] = useState<string | 'all'>('all');
  const [perfFilterJobTitle, setPerfFilterJobTitle] = useState<string | 'all'>('all');

  // Cascading helper: get teams for a selected department
  const getTeamsForDept = useCallback((deptId: number | 'all') => {
    if (deptId === 'all') {
      const allTeamsSet = new Set<string>();
      departments.forEach(d => {
        let tArr: any[] = [];
        if (Array.isArray(d.teams)) tArr = d.teams;
        else if (typeof d.teams === 'string') {
          try { tArr = JSON.parse(d.teams); } catch (e) {}
        }
        tArr.forEach(t => {
          const tName = typeof t === 'string' ? t : t.name;
          if (tName) allTeamsSet.add(tName);
        });
      });
      employees.forEach(e => {
        const tName = e.team_name || e.personal_info?.team_name;
        if (tName) allTeamsSet.add(tName);
      });
      return Array.from(allTeamsSet);
    }

    const dept = departments.find(d => d.id === deptId);
    const teamsSet = new Set<string>();
    if (dept) {
      let tArr: any[] = [];
      if (Array.isArray(dept.teams)) tArr = dept.teams;
      else if (typeof dept.teams === 'string') {
        try { tArr = JSON.parse(dept.teams); } catch (e) {}
      }
      tArr.forEach(t => {
        const name = typeof t === 'string' ? t : t.name;
        if (name) teamsSet.add(name);
      });
    }

    employees.filter(e => e.department_id === deptId).forEach(e => {
      const tName = e.team_name || e.personal_info?.team_name;
      if (tName) teamsSet.add(tName);
    });

    return Array.from(teamsSet);
  }, [departments, employees]);

  // Cascading helper: get job titles for a selected department & team
  const getJobTitlesForDeptAndTeam = useCallback((deptId: number | 'all', teamName: string | 'all') => {
    const titlesSet = new Set<string>();
    let targetDepts = departments;
    if (deptId !== 'all') {
      targetDepts = departments.filter(d => d.id === deptId);
    }

    targetDepts.forEach(d => {
      let jTitles: string[] = [];
      if (Array.isArray(d.job_titles)) jTitles = d.job_titles;
      else if (typeof d.job_titles === 'string') {
        try { jTitles = JSON.parse(d.job_titles); } catch (e) {}
      }

      let tArr: any[] = [];
      if (Array.isArray(d.teams)) tArr = d.teams;
      else if (typeof d.teams === 'string') {
        try { tArr = JSON.parse(d.teams); } catch (e) {}
      }

      tArr.forEach(t => {
        const name = typeof t === 'string' ? t : t.name;
        if (typeof t !== 'string' && (teamName === 'all' || name === teamName)) {
          if (Array.isArray(t.job_titles)) {
            t.job_titles.forEach((jt: any) => {
              const s = typeof jt === 'string' ? jt : (jt?.title || jt?.name);
              if (s) titlesSet.add(s);
            });
          }
        }
      });

      if (teamName === 'all') {
        jTitles.forEach((jt: any) => {
          const s = typeof jt === 'string' ? jt : (jt?.title || jt?.name);
          if (s) titlesSet.add(s);
        });
      }
    });

    employees.forEach(emp => {
      const matchDept = deptId === 'all' || emp.department_id === deptId;
      const empTeam = emp.team_name || emp.personal_info?.team_name || '';
      const matchTeam = teamName === 'all' || empTeam === teamName;
      if (matchDept && matchTeam && emp.job_title) {
        titlesSet.add(emp.job_title);
      }
    });

    return Array.from(titlesSet);
  }, [departments, employees]);

  // Cascading helper: get managers, department heads, and team leads for a selected department
  const getDepartmentManagerOptions = useCallback((
    deptIdOrName: any,
    currentEmpId?: any,
    currentJobTitle?: string
  ) => {
    // Find department object
    const selectedDeptObj = departments.find(d => 
      (d.id && String(d.id) === String(deptIdOrName)) || 
      (d.name && (d.name || '').toLowerCase() === String(deptIdOrName).toLowerCase())
    );

    const titleLower = (currentJobTitle || '').toLowerCase();
    
    // Check if employee is Department Head
    let isDeptHead = false;
    if (selectedDeptObj) {
      const headId = selectedDeptObj.department_head_id || (selectedDeptObj as any).head_id;
      if (headId && currentEmpId && (String(headId) === String(currentEmpId))) {
        isDeptHead = true;
      }
      const headName = (selectedDeptObj as any).department_head_name || (selectedDeptObj as any).head_name || (selectedDeptObj as any).manager_name;
      if (headName && currentEmpId) {
        const curEmp = employees.find(e => e.id === currentEmpId || e.user_id === currentEmpId);
        if (curEmp && curEmp.name && (curEmp.name || '').toLowerCase() === (headName || '').toLowerCase()) {
          isDeptHead = true;
        }
      }
    }
    if (titleLower.includes('department head') || titleLower.includes('head of department') || titleLower.includes('head of') || titleLower === 'department head') {
      isDeptHead = true;
    }

    const options: { value: string | number; label: string; isCeoMd?: boolean; isHead?: boolean }[] = [];
    const addedKeys = new Set<string>();

    const addOption = (val: string | number, label: string, isCeoMd = false, isHead = false) => {
      const key = `${val}_${label}`;
      if (!addedKeys.has(key)) {
        addedKeys.add(key);
        options.push({ value: val, label, isCeoMd, isHead });
      }
    };

    // 0. Board of Directors / No Manager
    addOption('No Manager / Board of Directors', 'No Manager / Board of Directors', true);

    // 1. CEO / MD leadership options
    const ceoMdEmps = employees.filter(e => {
      if (currentEmpId && (e.id === currentEmpId || e.user_id === currentEmpId)) return false;
      const jt = (e.job_title || '').toLowerCase();
      return jt.includes('ceo') || jt.includes('md') || jt.includes('managing director') || jt.includes('chief executive') || jt.includes('president') || jt.includes('executive director');
    });

    if (ceoMdEmps.length > 0) {
      ceoMdEmps.forEach(ceo => {
        addOption(ceo.id || ceo.name, `${ceo.name} (${ceo.job_title || 'CEO / MD'})`, true);
      });
    }
    
    // Standard default CEO and MD entries if not already added
    addOption('CEO', 'Chief Executive Officer (CEO)', true);
    addOption('MD', 'Managing Director (MD)', true);

    if (selectedDeptObj) {
      // 2. Department Head of selected department
      const headId = selectedDeptObj.department_head_id || (selectedDeptObj as any).head_id;
      const headName = (selectedDeptObj as any).department_head_name || (selectedDeptObj as any).head_name || (selectedDeptObj as any).manager_name;

      if (headId) {
        const matchEmp = employees.find(e => (e.id === headId || e.user_id === headId) && e.id !== currentEmpId);
        if (matchEmp) {
          addOption(matchEmp.id, `${matchEmp.name} (Department Head - ${selectedDeptObj.name})`, false, true);
        } else if (headName) {
          addOption(headName, `${headName} (Department Head - ${selectedDeptObj.name})`, false, true);
        }
      } else if (headName) {
        addOption(headName, `${headName} (Department Head - ${selectedDeptObj.name})`, false, true);
      }

      // Department employees with "Head", "Director", or "Manager" in title
      employees.forEach(e => {
        if (currentEmpId && (e.id === currentEmpId || e.user_id === currentEmpId)) return;
        const belongsToDept = (e.department_id && String(e.department_id) === String(selectedDeptObj.id)) || 
                              (e.department_name && selectedDeptObj?.name && (e.department_name || '').toLowerCase() === (selectedDeptObj.name || '').toLowerCase());
        if (belongsToDept) {
          const jt = (e.job_title || '').toLowerCase();
          if (jt.includes('head') || jt.includes('director') || jt.includes('manager')) {
            addOption(e.id, `${e.name} (${e.job_title || 'Manager'})`);
          }
        }
      });

      // 3. Team Leads of teams under selected department
      let teamsArr: any[] = [];
      if (Array.isArray(selectedDeptObj.teams)) teamsArr = selectedDeptObj.teams;
      else if (typeof selectedDeptObj.teams === 'string') {
        try { teamsArr = JSON.parse(selectedDeptObj.teams); } catch (e) {}
      }

      teamsArr.forEach(team => {
        if (typeof team === 'object' && team !== null) {
          const leadId = team.team_lead_id || team.lead_id;
          const leadName = team.team_lead_name || team.leader_name || team.lead_name || team.team_lead;
          const teamLabel = team.name ? `Team Lead - ${team.name}` : 'Team Lead';

          if (leadId) {
            const matchEmp = employees.find(e => (e.id === leadId || e.user_id === leadId) && e.id !== currentEmpId);
            if (matchEmp) {
              addOption(matchEmp.id, `${matchEmp.name} (${teamLabel})`);
            } else if (leadName) {
              addOption(leadName, `${leadName} (${teamLabel})`);
            }
          } else if (leadName) {
            addOption(leadName, `${leadName} (${teamLabel})`);
          }
        }
      });

      // 4. Other employees belonging to this department
      employees.forEach(e => {
        if (currentEmpId && (e.id === currentEmpId || e.user_id === currentEmpId)) return;
        const belongsToDept = (e.department_id && String(e.department_id) === String(selectedDeptObj.id)) || 
                              (e.department_name && selectedDeptObj?.name && (e.department_name || '').toLowerCase() === (selectedDeptObj.name || '').toLowerCase());
        if (belongsToDept) {
          addOption(e.id, `${e.name} (${e.job_title || 'Employee'})`);
        }
      });
    } else {
      // Fallback: list all employees if no department selected
      employees.forEach(e => {
        if (currentEmpId && (e.id === currentEmpId || e.user_id === currentEmpId)) return;
        addOption(e.id, `${e.name} (${e.job_title || 'Employee'})`);
      });
    }

    return { options, isDeptHead, selectedDeptObj };
  }, [departments, employees]);

  // Cascading helper: filter employees by Department -> Team -> Job Title
  const getFilteredEmployeesCascading = useCallback((
    deptId: number | 'all',
    teamName: string | 'all',
    jobTitle: string | 'all'
  ) => {
    return employees.filter(emp => {
      if (deptId !== 'all' && emp.department_id !== deptId) return false;
      const empTeam = emp.team_name || emp.personal_info?.team_name || '';
      if (teamName !== 'all' && empTeam !== teamName) return false;
      if (jobTitle !== 'all' && emp.job_title !== jobTitle) return false;
      return true;
    });
  }, [employees]);

  const fetchLiveEvaluations = async (start?: string, end?: string, deptId?: number | 'all') => {
    setIsLoadingLiveEvaluations(true);
    try {
      const s = start || perfFilterStartDate;
      const e = end || perfFilterEndDate;
      const d = deptId || perfFilterDept;
      let url = `/api/hr/performance/evaluate-all?startDate=${s}&endDate=${e}`;
      if (d !== 'all') {
        url += `&departmentId=${d}`;
      }
      const headers = { 'x-user-id': currentUser?.id?.toString() || '1' };
      const res = await fetchWithRetry(url, { headers });
      const evals = await safeJsonResponse(res, []);
      if (Array.isArray(evals)) {
        setLiveEvaluations(evals);
      }
    } catch (err) {
      console.warn('Failed to fetch live evaluations:', err);
    } finally {
      setIsLoadingLiveEvaluations(false);
    }
  };

  const loadedTabsRef = useRef<Set<string>>(new Set());

  const fetchEndpoint = async <T = any>(url: string, fallback: T | null = null): Promise<T | null> => {
    try {
      const headers = { 'x-user-id': currentUser?.id?.toString() || '1' };
      const res = await fetchWithRetry(url, { headers }, 1, 300);
      return await safeJsonResponse<T>(res, fallback);
    } catch (err) {
      console.warn(`Failed to fetch ${url}:`, err);
      return fallback;
    }
  };

  const fetchCoreData = async () => {
    try {
      const isDirectoryHidden = !isHRAdmin && !isSuperAdmin && (
        isScreenHidden('directory', 'HR') || 
        !allowedHrTabs.some(t => t.id === 'directory' || t.id === 'archived')
      );
      const isDeptHidden = !isHRAdmin && !isSuperAdmin && (
        isScreenHidden('departments', 'HR') || 
        !allowedHrTabs.some(t => t.id === 'departments' || t.id === 'orgchart')
      );

      const promises: Promise<any>[] = [];
      if (!isDirectoryHidden) {
        promises.push(
          fetchEndpoint('/api/hr/employees').then((empData: any) => {
            if (empData) {
              setEmployees(empData);
              try { localStorage.setItem('hr_cached_employees', JSON.stringify(empData)); } catch {}
              setViewingEmployee((prev: any) => {
                if (!prev) return null;
                const fresh = empData.find((e: any) => e.id === prev.id || e.user_id === prev.id || e.id === prev.user_id);
                return fresh ? { ...prev, ...fresh } : prev;
              });
            }
          })
        );
      }
      if (!isDeptHidden) {
        promises.push(
          fetchEndpoint('/api/departments').then((deptData: any) => {
            if (deptData) {
              setDepartments(deptData);
              try { localStorage.setItem('hr_cached_departments', JSON.stringify(deptData)); } catch {}
            }
          })
        );
      }
      if (promises.length > 0) {
        await Promise.all(promises);
      }
    } catch (err) {
      console.error('Failed to fetch HR core data:', err);
    }
  };

  const fetchTabData = async (tab: string, force = false) => {
    if (!tab) return;
    // CRITICAL USER REQUIREMENT: Do NOT execute any query for hidden tabs!
    // "المفروض الحاجه اللي امنع رؤيتها متظهرش نهائيا و متعملهاش اي استعلام خالص"
    if (!isHRAdmin && !isSuperAdmin) {
      const isHidden = isScreenHidden(tab, 'HR') || !allowedHrTabs.some(t => t.id === tab);
      if (isHidden) {
        return;
      }
    }

    if (!force && loadedTabsRef.current.has(tab)) {
      return;
    }

    try {
      // Always ensure core employees/departments are present
      if (rawEmployees.length === 0 || rawDepartments.length === 0) {
        await fetchCoreData();
      }

      switch (tab) {
        case 'dashboard': {
          // Dashboard needs light counts, core data
          await fetchCoreData();
          break;
        }
        case 'directory':
        case 'orgchart':
        case 'departments': {
          await fetchCoreData();
          break;
        }
        case 'recruitment': {
          const pipelinesData = await fetchEndpoint('/api/hr/pipelines');
          if (pipelinesData) setPipelines(pipelinesData);
          break;
        }
        case 'payroll': {
          const [payData, configData] = await Promise.all([
            fetchEndpoint('/api/hr/payroll'),
            fetchEndpoint('/api/hr/payroll/config')
          ]);
          if (payData) setPayroll(payData);
          if (configData) setPayrollConfig(configData);
          break;
        }
        case 'attendance': {
          const [attData, shiftData, shiftAssignData, swapData, leaveData, logsData] = await Promise.all([
            fetchEndpoint('/api/hr/attendance'),
            fetchEndpoint('/api/hr/shifts'),
            fetchEndpoint('/api/hr/shift-assignments'),
            fetchEndpoint('/api/hr/shift-swaps'),
            fetchEndpoint('/api/hr/leave'),
            fetchEndpoint('/api/hr/logs')
          ]);
          if (attData) setAttendance(attData);
          if (shiftData) setShifts(shiftData);
          if (shiftAssignData) setShiftAssignments(shiftAssignData);
          if (swapData) setShiftSwaps(swapData);
          if (leaveData) setLeaves(leaveData);
          if (logsData) setHrLogs(logsData);
          break;
        }
        case 'performance': {
          const perfData = await fetchEndpoint('/api/hr/performance');
          if (perfData) setPerformance(perfData);
          fetchLiveEvaluations().catch(() => null);
          break;
        }
        case 'complaints': {
          const compData = await fetchEndpoint('/api/hr/complaints');
          if (compData) setComplaints(compData);
          break;
        }
        default:
          break;
      }

      loadedTabsRef.current.add(tab);
    } catch (err) {
      console.error(`Failed to fetch tab data for [${tab}]:`, err);
    } finally {
      setLoading(false);
    }
  };

  const fetchData = async (options?: { silent?: boolean }) => {
    // Lazy fetch current active tab specifically
    await fetchTabData(activeTab, true);
  };

  // Lazy fetch data whenever activeTab changes
  useEffect(() => {
    fetchTabData(activeTab);
  }, [activeTab, currentUser]);

  useEffect(() => {
    const handleSynced = () => {
      fetchTabData(activeTab, true);
    };
    window.addEventListener('hr_attendance_synced', handleSynced);
    return () => {
      window.removeEventListener('hr_attendance_synced', handleSynced);
    };
  }, [activeTab]);

  // Background auto-refresh for Directory to keep 100+ multi-user concurrent sessions synchronized
  useEffect(() => {
    if (activeTab !== 'directory') return;
    const interval = setInterval(() => {
      // Pause background poll if user is actively viewing/editing an employee profile to prevent race conditions
      if (viewingEmployee || isProfileDirty) return;
      fetchData({ silent: true }).catch(() => null);
    }, 25000); // Poll every 25 seconds quietly
    return () => clearInterval(interval);
  }, [activeTab, viewingEmployee, isProfileDirty]);

  // Reset directory pagination whenever filters or search terms change
  useEffect(() => {
    setDirectoryPage(1);
  }, [directorySearch, directoryFilter, directoryTeamFilter, directoryJobTitleFilter, advancedFilteredEmployees]);

  const handleManualDirectoryRefresh = async () => {
    setIsRefreshingDirectory(true);
    try {
      await fetchData({ silent: false });
      showCustomToast('Directory refreshed with latest database records', 'success');
    } catch (e) {
      console.error(e);
    } finally {
      setIsRefreshingDirectory(false);
    }
  };

  const updateLeaveStatus = async (id: number, status: string) => {
    try {
      const res = await fetch(`/api/hr/leave/${id}`, {
        method: 'PATCH',
        headers: { 
          'Content-Type': 'application/json',
          'x-user-id': currentUser?.id?.toString() || '1'
        },
        body: JSON.stringify({ 
          status, 
          approver_id: currentUser?.id,
          comments: `Leave ${(status || '').toLowerCase()} by HR/Manager.`
        })
      });
      if (res.ok) {
        alert(`Leave request ${(status || '').toLowerCase()} successfully.`);
        fetchData();
      }
    } catch (err) {
      console.error('Failed to update leave request:', err);
    }
  };

  const handleSubmitReview = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const res = await fetch('/api/hr/performance', {
        method: 'POST',
        headers: { 
          'Content-Type': 'application/json',
          'x-user-id': currentUser?.id?.toString() || '1'
        },
        body: JSON.stringify({ ...reviewFormData, reviewer_id: currentUser?.id })
      });
      if (res.ok) {
        let savedId = reviewFormData.id;
        try {
          const result = await res.json();
          savedId = result.id || (Array.isArray(result) ? result[0]?.id : null) || savedId;
        } catch (e) {}
        if (savedId) {
          await saveCustomFieldValues(savedId, performanceCustomFieldValues);
        }
        setShowPerformanceModal(false);
        fetchData();
        alert('Performance review saved successfully!');
      }
    } catch (err) {
      console.error('Failed to save performance review:', err);
    }
  };

  const handleEvaluateEmployee = async (emp: Employee) => {
    try {
      const res = await fetch(`/api/hr/performance/evaluate/${emp.id}`, {
        headers: { 'x-user-id': currentUser?.id?.toString() || '1' }
      });
      if (res.ok) {
        const result = await res.json();
        const kpiText = result.hasKpis 
          ? ` | Active KPIs achievement: ${result.kpiRate.toFixed(1)}% across ${result.kpis.length} KPIs.`
          : '';
        setReviewFormData({
          id: null,
          user_id: emp.id,
          period: result.period,
          score: parseFloat(result.score.toFixed(1)),
          productivity_rate: Math.round(result.productivity_rate),
          strengths: `Total Tasks: ${result.total_tasks}, Completed: ${result.completed_tasks}${kpiText}`,
          areas_for_improvement: result.hasKpis ? 'Keep up with the high-performance KPI standards.' : 'Link more KPIs to track quantitative results.',
          status: 'Finalized',
          created_at: new Date().toISOString().slice(0, 16)
        });
        setShowPerformanceModal(true);
      }
    } catch (err) {
      console.error('Failed to run automated evaluation:', err);
    }
  };

  const handleDeleteEmployee = async () => {
    if (!showDeleteConfirm) return;
    try {
      const queryParam = reassignTargetUserId ? `?reassignToUserId=${reassignTargetUserId}` : '';
      const res = await fetch(`/api/hr/employees/${showDeleteConfirm}${queryParam}`, {
        method: 'DELETE',
        headers: {
          'x-user-id': currentUser?.id?.toString() || '1'
        }
      });
      if (res.ok) {
        setShowDeleteConfirm(null);
        setReassignTargetUserId('');
        if (viewingEmployee?.id === showDeleteConfirm) setViewingEmployee(null);
        showCustomToast('تم حذف الموظف وتحويل الأعمال بنجاح', 'success');
        fetchData();
      } else {
        const data = await res.json().catch(() => ({}));
        alert(data.error || 'Failed to delete employee. Please check if they have associated records.');
      }
    } catch (err) {
      console.error('Failed to delete employee:', err);
    }
  };

  const handleDeletePayroll = async () => {
    if (!showPayrollDeleteConfirm) return;
    try {
      const res = await fetch(`/api/hr/payroll/${showPayrollDeleteConfirm}`, {
        method: 'DELETE',
        headers: {
          'x-user-id': currentUser?.id?.toString() || '1'
        }
      });
      if (res.ok) {
        setShowPayrollDeleteConfirm(null);
        fetchData();
        alert('Payroll record deleted successfully.');
      } else {
        const err = await res.json();
        alert(err.error || 'Failed to delete payroll record.');
      }
    } catch (err) {
      console.error('Failed to delete payroll:', err);
    } finally {
      setShowPayrollDeleteConfirm(null);
    }
  };

  const syncJDsForDeptObject = async (deptObj: any) => {
    try {
      const deptName = deptObj.name;
      if (!deptName) return;

      let rawTitles: any[] = [];
      if (Array.isArray(deptObj.job_titles)) rawTitles = deptObj.job_titles;
      else if (typeof deptObj.job_titles === 'string') {
        try { rawTitles = JSON.parse(deptObj.job_titles); } catch (e) {}
      }

      let rawTeams: any[] = [];
      if (Array.isArray(deptObj.teams)) rawTeams = deptObj.teams;
      else if (typeof deptObj.teams === 'string') {
        try { rawTeams = JSON.parse(deptObj.teams); } catch (e) {}
      }

      const titleToTeamMap = new Map<string, string>();

      rawTeams.forEach((t: any) => {
        const tName = typeof t === 'string' ? t : (t?.name || '');
        const tTitles = Array.isArray(t?.job_titles) ? t.job_titles : (Array.isArray(t?.jobTitles) ? t.jobTitles : []);
        tTitles.forEach((jt: any) => {
          const titleStr = typeof jt === 'string' ? jt : (jt?.title || jt?.name || '');
          if (titleStr) {
            titleToTeamMap.set(titleStr.trim(), tName);
          }
        });
      });

      rawTitles.forEach((jt: any) => {
        const titleStr = typeof jt === 'string' ? jt : (jt?.title || jt?.name || '');
        if (titleStr) {
          const trimmed = titleStr.trim();
          if (!titleToTeamMap.has(trimmed)) {
            titleToTeamMap.set(trimmed, '');
          }
        }
      });

      let dbJDs: any[] = [];
      try {
        const resGet = await fetch('/api/job_descriptions');
        if (resGet.ok) {
          dbJDs = await resGet.json();
        }
      } catch (e) {}

      let customJDsMap: Record<string, any> = {};
      try {
        const local = localStorage.getItem('systo_custom_jds');
        if (local) customJDsMap = JSON.parse(local);
      } catch (e) {}

      for (const [titleStr, teamName] of titleToTeamMap.entries()) {
        const existingDb = Array.isArray(dbJDs) ? dbJDs.find((item: any) => item.title?.toLowerCase() === (titleStr || '').toLowerCase()) : null;

        const jdDetails = {
          department: deptName,
          team: teamName || '',
          grade: existingDb?.grade || 'Grade 3 / Mid-Senior',
          salaryBand: existingDb?.salary_band || '',
          reportsTo: existingDb?.reports_to || `${deptName} Manager`,
          employmentType: existingDb?.employment_type || 'Full-Time',
          location: existingDb?.location || 'On-Site',
          status: existingDb?.status || 'Approved',
          objective: existingDb?.objective || `Drive key operational deliverables as a ${titleStr} within ${deptName}.`,
          responsibilities: existingDb?.responsibilities
            ? (typeof existingDb.responsibilities === 'string' ? JSON.parse(existingDb.responsibilities) : existingDb.responsibilities)
            : [
                `Execute primary business deliverables aligned with the ${titleStr} functional scope.`,
                `Collaborate with team members and department leadership.`,
                `Maintain quality standards and operational compliance.`
              ],
          education: existingDb?.education || "Bachelor's degree in a relevant discipline or equivalent practical experience.",
          technicalSkills: existingDb?.technical_skills
            ? (typeof existingDb.technical_skills === 'string' ? JSON.parse(existingDb.technical_skills) : existingDb.technical_skills)
            : ['Domain Operations', 'Process Optimization'],
          softSkills: existingDb?.soft_skills
            ? (typeof existingDb.soft_skills === 'string' ? JSON.parse(existingDb.soft_skills) : existingDb.soft_skills)
            : ['Teamwork', 'Communication', 'Problem Solving'],
          certifications: existingDb?.certifications
            ? (typeof existingDb.certifications === 'string' ? JSON.parse(existingDb.certifications) : existingDb.certifications)
            : [],
          kpis: existingDb?.kpis
            ? (typeof existingDb.kpis === 'string' ? JSON.parse(existingDb.kpis) : existingDb.kpis)
            : ['Quarterly Task Fulfillment ≥ 90%'],
          raciRole: existingDb?.raci_role || 'Responsible'
        };

        customJDsMap[titleStr] = jdDetails;

        const payload = {
          title: titleStr,
          department: deptName,
          team: teamName || '',
          grade: jdDetails.grade,
          salary_band: jdDetails.salaryBand,
          reports_to: jdDetails.reportsTo,
          employment_type: jdDetails.employmentType,
          location: jdDetails.location,
          status: jdDetails.status,
          objective: jdDetails.objective,
          responsibilities: JSON.stringify(jdDetails.responsibilities),
          education: jdDetails.education,
          technical_skills: JSON.stringify(jdDetails.technicalSkills),
          soft_skills: JSON.stringify(jdDetails.softSkills),
          certifications: JSON.stringify(jdDetails.certifications),
          kpis: JSON.stringify(jdDetails.kpis),
          raci_role: jdDetails.raciRole,
          jd_data: JSON.stringify(jdDetails)
        };

        if (existingDb && existingDb.id) {
          await fetch(`/api/job_descriptions/${existingDb.id}`, {
            method: 'PUT',
            headers: { 'Content-Type': 'application/json', 'x-user-id': '1' },
            body: JSON.stringify(payload)
          });
        } else {
          await fetch('/api/job_descriptions', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json', 'x-user-id': '1' },
            body: JSON.stringify(payload)
          });
        }
      }

      try {
        localStorage.setItem('systo_custom_jds', JSON.stringify(customJDsMap));
      } catch (e) {}
    } catch (err) {
      console.warn('Error syncing JDs for department:', err);
    }
  };

  const handleSaveDept = async (deptData: any) => {
    try {
      const targetDept = deptData?.name ? deptData : editingDept;
      if (!targetDept?.name) {
        alert('Department name is required.');
        return;
      }

      const payload = {
        name: targetDept.name,
        description: targetDept.description || '',
        department_head_id: targetDept.department_head_id ? parseInt(targetDept.department_head_id) : null,
        teams: typeof targetDept.teams === 'string' ? targetDept.teams : JSON.stringify(targetDept.teams || []),
        job_titles: typeof targetDept.job_titles === 'string' ? targetDept.job_titles : JSON.stringify(targetDept.job_titles || [])
      };

      const deptId = targetDept.id || editingDept?.id;
      const method = deptId ? 'PUT' : 'POST';
      const url = deptId ? `/api/departments/${deptId}` : '/api/departments';

      const res = await fetch(url, {
        method,
        headers: {
          'Content-Type': 'application/json',
          'x-user-id': currentUser?.id?.toString() || '1'
        },
        body: JSON.stringify(payload)
      });

      if (!res.ok) {
        const errorMsg = await res.text();
        throw new Error(errorMsg || 'Failed to save department');
      }

      await syncJDsForDeptObject(targetDept);

      setIsDeptModalOpen(false);
      setEditingDept(null);
      fetchData();
      showCustomToast(`Department ${deptId ? 'updated' : 'created'} successfully!`, 'success');
    } catch (err) {
      console.error('Failed to save department:', err);
      alert(`Error: ${err instanceof Error ? err.message : String(err)}`);
    }
  };

  const handleDeleteDept = async () => {
    if (!showDeptDeleteConfirm) return;
    try {
      const res = await fetch(`/api/departments/${showDeptDeleteConfirm}`, {
        method: 'DELETE',
        headers: {
          'x-user-id': currentUser?.id?.toString() || '1'
        }
      });

      if (!res.ok) {
        throw new Error('Failed to delete department');
      }

      setShowDeptDeleteConfirm(null);
      fetchData();
      alert('Department deleted successfully.');
    } catch (err) {
      console.error('Failed to delete department:', err);
      alert('Failed to delete department. Please make sure this department has no assigned employees.');
    }
  };

  const handleAction = async (action: string, data?: any) => {
    if (action === 'Add Employee') {
      setSelectedEmployee(null);
      setFormData({
        name: '',
        email: '',
        phone: '',
        id_number: '',
        job_title: '',
        department_id: 1,
        salary_base: 0,
        allowances: 0,
        contract_type: 'Full-time',
        contract_start_date: new Date().toISOString().split('T')[0],
        contract_end_date: '',
        vacation_balance: 0,
        status: 'active',
        joined_at: new Date().toISOString().split('T')[0],
        documents: [],
        penalty_history: []
      });
      setShowAddModal(true);
      return;
    }

    if (action === 'Edit Employee' && data) {
        setIsViewOnlyMode(false);
        setViewingEmployee(data);
        return;
    }
    
    if (action === 'Delete Employee' && data) {
        setShowDeleteConfirm(data.id);
        return;
    }

    if (action === 'Approve Leave' && data) {
      updateLeaveStatus(data.id, 'Approved');
      return;
    }

    if (action === 'Reject Leave' && data) {
      updateLeaveStatus(data.id, 'Rejected');
      return;
    }

    if (action === 'New Evaluation') {
      setReviewFormData({
        id: null,
        user_id: employees[0]?.id || 0,
        period: 'Monthly',
        score: 5,
        productivity_rate: 80,
        strengths: '',
        areas_for_improvement: '',
        status: 'Finalized',
        created_at: new Date().toISOString().slice(0, 16)
      });
      setShowPerformanceModal(true);
      return;
    }

    if (action === 'Evaluate Now' && data) {
      handleEvaluateEmployee(data);
      return;
    }

    if (action === 'ANALYSIS' && data) {
      try {
        setAnalyzedEmployee(data);
        const res = await fetch(`/api/hr/performance/evaluate/${data.id}?startDate=${analysisStartDate}&endDate=${analysisEndDate}`, {
          headers: { 'x-user-id': currentUser?.id?.toString() || '1' }
        });
        if (res.ok) {
          setPerformanceAnalysis(await res.json());
        }
      } catch (err) {
        console.error('Failed to fetch analysis:', err);
      }
      return;
    }
    
    console.log(`HR Action: ${action}`, data);
    if (action.includes('Process') || action.includes('Evaluate') || action.includes('Approve')) {
      alert(`${action} triggered successfully!`);
      fetchData();
    }
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    try {
      const isEdit = !!selectedEmployee;
      const url = isEdit ? `/api/hr/employees/${selectedEmployee.id}` : '/api/hr/employees';
      const method = isEdit ? 'PUT' : 'POST';

      const pInfo = formData.personal_info || {};
      const nameParts = [pInfo.first_name, pInfo.middle_name, pInfo.last_name].filter(Boolean);
      const computedName = nameParts.length > 0 ? nameParts.join(' ') : (formData.name || 'New Employee');
      const primaryEmail = pInfo.work_email || formData.email || '';
      const primaryPhone = pInfo.mobile_phone || pInfo.work_phone || formData.phone || '';
      const primarySalary = pInfo.pay_rate ? parseFloat(pInfo.pay_rate) : (formData.salary_base || 0);
      const primaryContract = pInfo.employment_status || formData.contract_type || 'Full-time';
      const primaryIdNum = pInfo.employee_number || formData.id_number || '';
      const hireDate = formData.joined_at || formData.contract_start_date || new Date().toISOString().split('T')[0];

      const updatedPersonalInfo = {
        ...pInfo,
        first_name: pInfo.first_name || '',
        middle_name: pInfo.middle_name || '',
        last_name: pInfo.last_name || '',
        preferred_name: pInfo.preferred_name || pInfo.first_name || '',
        employee_number: primaryIdNum,
        birth_date: pInfo.birth_date || '',
        gender: pInfo.gender || '',
        marital_status: pInfo.marital_status || '',
        nin: pInfo.nin || primaryIdNum || '',
        shirt_size: pInfo.shirt_size || '',
        bank_details_copy: pInfo.bank_details_copy || '',
        
        street_1: pInfo.street_1 || '',
        street_2: pInfo.street_2 || '',
        city: pInfo.city || '',
        province: pInfo.province || '',
        county: pInfo.province || '',
        postcode: pInfo.postcode || '',
        country: pInfo.country || 'Egypt',

        pay_schedule: pInfo.pay_schedule || 'Monthly',
        pay_type: pInfo.pay_type || 'Salary',
        pay_rate: pInfo.pay_rate || primarySalary.toString(),
        pay_per: pInfo.pay_per || 'Month',
        currency: pInfo.currency || 'EGP',

        work_phone: pInfo.work_phone || primaryPhone,
        ext: pInfo.ext || '',
        mobile_phone: pInfo.mobile_phone || primaryPhone,
        home_phone: pInfo.home_phone || '',
        work_email: primaryEmail,
        home_email: pInfo.home_email || '',

        employment_status: primaryContract,
        division: pInfo.division || '',
        location: pInfo.location || '',
        self_service_access: pInfo.self_service_access || 'allow',
        role_id: pInfo.self_service_access === 'no_access' ? null : (formData.role_id || pInfo.role_id || null),
      };

      const rawReportingTo = formData.reporting_to;
      const parsedNumReportingTo = Number(rawReportingTo);
      const reportingToValue: any = (rawReportingTo !== undefined && rawReportingTo !== null && (rawReportingTo as any) !== '')
        ? (!isNaN(parsedNumReportingTo) ? parsedNumReportingTo : rawReportingTo)
        : null;

      let computedManagerName = '';
      if (reportingToValue) {
        const matchMgr = employees.find(e => String(e.id) === String(reportingToValue) || String(e.user_id) === String(reportingToValue));
        if (matchMgr) {
          computedManagerName = matchMgr.name;
        } else if (typeof reportingToValue === 'string') {
          computedManagerName = reportingToValue;
        }
      }

      const selectedDeptObj = departments.find(d => 
        (formData.department_id && String(d.id) === String(formData.department_id)) ||
        (formData.department_name && d.name === formData.department_name)
      );
      const computedDeptName = selectedDeptObj?.name || formData.department_name || 'Human Resources';

      const initialJobInfo = {
        id: `job-info-init-${Date.now()}`,
        date: hireDate,
        location: pInfo.location || 'Cairo, Egypt',
        division: pInfo.division || (selectedDeptObj as any)?.division || '',
        department: computedDeptName,
        teams: formData.team_name || '',
        jobTitle: formData.job_title || 'Employee',
        reportingTo: computedManagerName || reportingToValue || 'Management',
        changeReason: 'Initial Contract Hire'
      };

      const initialComp = {
        id: `comp-init-${Date.now()}`,
        date: hireDate,
        paySchedule: pInfo.pay_schedule || 'Monthly',
        payType: pInfo.pay_type || 'Salary',
        payRate: primarySalary,
        paidPer: pInfo.pay_per || 'Month',
        overtimeStatus: 'Exempt',
        changeReason: 'Initial Base Salary',
        comments: 'Hire Salary Policy',
        isActive: true
      };

      const initialStatus = {
        id: `status-init-${Date.now()}`,
        date: hireDate,
        status: primaryContract,
        comments: `Initial Hire Status (${formData.status || 'Active'})`,
        isActive: true
      };

      const sanitizedData = {
        ...formData,
        role_id: pInfo.self_service_access === 'no_access' ? null : (formData.role_id || pInfo.role_id || null),
        name: computedName,
        email: primaryEmail,
        phone: primaryPhone,
        id_number: primaryIdNum,
        salary_base: primarySalary,
        contract_type: primaryContract,
        department_id: formData.department_id ? (isNaN(Number(formData.department_id)) ? formData.department_id : parseInt(formData.department_id.toString())) : (departments[0]?.id || 1),
        department_name: computedDeptName,
        team_name: formData.team_name || '',
        job_title: formData.job_title || 'Employee',
        reporting_to: reportingToValue,
        manager_name: computedManagerName,
        contract_start_date: hireDate,
        contract_end_date: formData.contract_end_date || null,
        joined_at: hireDate,
        status: formData.status || 'active',
        job_informations: (formData.job_informations && formData.job_informations.length > 0) 
          ? formData.job_informations 
          : [initialJobInfo],
        compensations: (formData.compensations && formData.compensations.length > 0) 
          ? formData.compensations 
          : [initialComp],
        employment_statuses: (formData.employment_statuses && formData.employment_statuses.length > 0) 
          ? formData.employment_statuses 
          : [initialStatus],
        personal_info: updatedPersonalInfo
      };

      const res = await fetch(url, {
        method,
        headers: { 
          'Content-Type': 'application/json',
          'x-user-id': currentUser?.id?.toString() || '1'
        },
        body: JSON.stringify(sanitizedData)
      });
      if (res.ok) {
        await syncEmployeeStatusWithUser(sanitizedData);
        let savedId = selectedEmployee?.id;
        try {
          const result = await res.json();
          savedId = result.id || (Array.isArray(result) ? result[0]?.id : null) || savedId;
        } catch (e) {}
        if (savedId) {
          await saveCustomFieldValues(savedId, customFieldValues);
        }
        setShowAddModal(false);
        setSelectedEmployee(null);
        fetchData();
        showCustomToast(isEdit ? 'Employee profile updated successfully!' : 'New employee added successfully!', 'success');
      } else {
        alert('Failed to save employee. Please check required fields.');
      }
    } catch (err) {
      console.error('Failed to save employee:', err);
      alert('An error occurred while saving employee.');
    }
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    try {
      showCustomToast(`Uploading ${file.name} to storage...`, 'info');
      const uploaded = await uploadFileToStorage(file, `employee-docs/${formData?.id || 'general'}`);
      const newDoc: EmployeeDocument = {
        id: Date.now(),
        name: uploaded.name || file.name,
        type: uploadType,
        url: uploaded.url,
        uploaded_at: new Date().toISOString()
      };
      const updatedDocs = [...(formData.documents || []), newDoc];
      setFormData({ ...formData, documents: updatedDocs });
      showCustomToast(`${file.name} uploaded successfully!`, 'success');
    } catch (err: any) {
      console.error('File upload error:', err);
      showCustomToast(`Failed to upload file: ${err.message || 'Error'}`, 'error');
    } finally {
      if (e.target) e.target.value = '';
    }
  };

  const triggerUpload = (type: string) => {
    setUploadType(type);
    fileInputRef.current?.click();
  };

  const addPenaltyRecord = () => {
    if (!newPenalty.reason || newPenalty.amount <= 0) return;
    const updatedHistory: PenaltyRecord[] = [...(formData.penalty_history || []), { ...newPenalty, id: Date.now() }];
    setFormData({ ...formData, penalty_history: updatedHistory });
    setNewPenalty({ type: 'Deduction', reason: '', amount: 0, date: new Date().toISOString().split('T')[0] });
    setShowPenaltyForm(false);
  };

  const handleAddLeaveType = () => {
    const trimmed = newLeaveTypeInput.trim();
    if (!trimmed) return;
    if (!availableLeaveTypes.includes(trimmed)) {
      const updated = [...availableLeaveTypes, trimmed];
      setAvailableLeaveTypes(updated);
      localStorage.setItem('hr_leave_types', JSON.stringify(updated));
      setLeaveFormData(prev => ({ ...prev, type: trimmed }));
      showCustomToast(`Leave type "${trimmed}" added!`);
    }
    setNewLeaveTypeInput('');
    setShowAddLeaveTypeInput(false);
  };

  const handleDeleteLeaveType = (typeToDelete: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (availableLeaveTypes.length <= 1) {
      showCustomToast('Cannot delete the last remaining leave type', 'error');
      return;
    }
    const updated = availableLeaveTypes.filter(t => t !== typeToDelete);
    setAvailableLeaveTypes(updated);
    localStorage.setItem('hr_leave_types', JSON.stringify(updated));
    if (leaveFormData.type === typeToDelete) {
      setLeaveFormData(prev => ({ ...prev, type: updated[0] || 'Annual Leave' }));
    }
    showCustomToast(`Leave type "${typeToDelete}" removed`);
  };

  const handleLeaveFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;
    try {
      showCustomToast(`Uploading ${file.name}...`, 'info');
      const uploaded = await uploadFileToStorage(file, `leave-attachments/${currentUser?.id || 'general'}`);
      setLeaveFormData(prev => ({
        ...prev,
        attachment_url: uploaded.url,
        attachment_name: file.name
      }));
      showCustomToast(`Attached file: ${file.name}`, 'success');
    } catch (err: any) {
      console.error('Leave attachment upload failed:', err);
      showCustomToast(`Failed to upload attachment: ${err.message || 'Error'}`, 'error');
    }
  };

