  const handleSaveAssignment = async (e: React.FormEvent) => {
    e.preventDefault();

    if (multiAssignmentForm.user_ids.length === 0) {
      showCustomToast('Please select at least one employee', 'error');
      return;
    }
    if (multiAssignmentForm.shift_ids.length === 0) {
      showCustomToast('Please select at least one shift', 'error');
      return;
    }
    if (multiAssignmentForm.days_of_week.length === 0) {
      showCustomToast('Please select at least one working day', 'error');
      return;
    }

    const assignments: { user_id: number; shift_id: number; day_of_week: number }[] = [];
    for (const uid of multiAssignmentForm.user_ids) {
      for (const sid of multiAssignmentForm.shift_ids) {
        for (const day of multiAssignmentForm.days_of_week) {
          assignments.push({ user_id: uid, shift_id: sid, day_of_week: day });
        }
      }
    }

    try {
      const res = await fetch('/api/hr/shift-assignments', {
        method: 'POST',
        headers: { 
          'Content-Type': 'application/json',
          'x-user-id': currentUser?.id?.toString() || '1'
        },
        body: JSON.stringify({ 
          assignments,
          clearExisting: clearExistingAssignments,
          user_ids: multiAssignmentForm.user_ids,
          days_of_week: multiAssignmentForm.days_of_week,
          startDate: scheduleStartDate,
          endDate: scheduleEndDate,
          recurrence: scheduleRecurrence,
          notificationTiming: notificationTiming,
          employee_visibility: employeeVisibility,
          is_published: employeeVisibility !== 'draft'
        })
      });
      if (res.ok) {
        showCustomToast('Shift schedule assigned and notifications sent successfully!', 'success');
        setShowAssignModal(false);
        fetchData();
      } else {
        showCustomToast('Failed to save shift assignments', 'error');
      }
    } catch (err) {
      console.error('Failed to save assignment:', err);
      showCustomToast('An error occurred while saving shift assignments', 'error');
    }
  };

  const handleSyncAttendance = async (isSilent: boolean = false) => {
    let sources: any[] = [];
    try {
      const saved = localStorage.getItem('hr_clocking_sources');
      if (saved) sources = JSON.parse(saved);
    } catch (e) {
      console.error('Failed to parse hr_clocking_sources', e);
    }

    setIsSyncing(true);
    try {
      const res = await fetch('/api/hr/attendance/sync', {
        method: 'POST',
        headers: { 
          'Content-Type': 'application/json',
          'x-user-id': currentUser?.id?.toString() || '1'
        },
        body: JSON.stringify({
          period: attendanceSyncPeriod,
          date_time: attendanceSyncTime,
          sources: sources
        })
      });
      if (res.ok) {
        const data = await res.json();
        setLastAutoSyncTime(new Date());
        if (!isSilent) {
          showCustomToast(data.message || 'Smart Sync completed successfully! Incremental records updated.', 'success');
        }
        fetchData();
      } else {
        if (!isSilent) {
          showCustomToast('Failed to perform Smart Sync', 'error');
        }
      }
    } catch (err) {
      console.error('Failed to sync attendance:', err);
      if (!isSilent) {
        showCustomToast('Error connecting to Smart Sync service', 'error');
      }
    } finally {
      setIsSyncing(false);
    }
  };

  const handleOpenAddEmployeeWithCandidate = (candidateData: any) => {
    setSelectedEmployee(null);

    const candidateName = candidateData?.name || '';
    const nameParts = candidateName.trim().split(/\s+/);
    const firstName = nameParts[0] || '';
    const lastName = nameParts.length > 1 ? nameParts[nameParts.length - 1] : '';
    const middleName = nameParts.length > 2 ? nameParts.slice(1, -1).join(' ') : '';

    let deptId = candidateData?.department_id || 1;
    if (!candidateData?.department_id && candidateData?.job_title) {
      const matchedDept = departments.find(d => 
        d.name?.toLowerCase().includes((candidateData.job_title || '').toLowerCase()) ||
        d.job_titles?.some((jt: string) => (jt || '').toLowerCase().includes((candidateData.job_title || '').toLowerCase()))
      );
      if (matchedDept) {
        deptId = matchedDept.id;
      }
    }

    const jobTitle = candidateData?.applied_role || candidateData?.job_title || 'New Hire';

    setFormData({
      name: candidateName,
      email: candidateData?.email || '',
      phone: candidateData?.phone || '',
      id_number: candidateData?.id ? `EMP-${String(candidateData.id).padStart(4, '0')}` : '',
      job_title: jobTitle,
      department_id: deptId,
      salary_base: candidateData?.salary_base || 0,
      allowances: 0,
      contract_type: 'Full-time',
      contract_start_date: new Date().toISOString().split('T')[0],
      contract_end_date: '',
      vacation_balance: 0,
      status: 'active',
      joined_at: new Date().toISOString().split('T')[0],
      documents: candidateData?.cv_url ? [{ id: Date.now(), name: 'Candidate CV / Resume', url: candidateData.cv_url, type: 'pdf', uploaded_at: new Date().toISOString().split('T')[0] }] : [],
      penalty_history: [],
      personal_info: {
        first_name: firstName,
        middle_name: middleName,
        last_name: lastName || firstName,
        preferred_name: firstName,
        work_email: candidateData?.email || '',
        personal_email: candidateData?.email || '',
        mobile_phone: candidateData?.phone || '',
        work_phone: candidateData?.phone || '',
        linkedin_url: candidateData?.linkedin_url || '',
        employee_number: candidateData?.id ? `EMP-${String(candidateData.id).padStart(4, '0')}` : '',
        notes: candidateData?.notes || '',
        comments: candidateData?.notes ? [{
          id: `comment-${Date.now()}`,
          author_name: 'Recruitment System',
          content: `Imported from Candidate Info (${candidateData?.stage || 'Hired'}). Notes: ${candidateData.notes}`,
          created_at: new Date().toISOString()
        }] : [],
        logs: [{
          id: `log-${Date.now()}`,
          action_type: 'created',
          details: `Imported candidate ${candidateName} from recruitment pipeline (${candidateData?.stage || 'Hired'}).`,
          created_at: new Date().toISOString()
        }]
      }
    });

    setActiveTab('directory');
    setShowAddModal(true);
  };

