                                                  {Math.floor(totalBreakMins / 60) > 0 ? `${Math.floor(totalBreakMins / 60)}h ` : ''}
                                                  {totalBreakMins % 60 > 0 ? `${totalBreakMins % 60}m` : (Math.floor(totalBreakMins / 60) > 0 ? '00m' : '0m')}
