                                      {sMethod === 'Fingerprint' && <Fingerprint className="w-3 h-3" />}
                                      {sMethod === 'Both' && <CheckCheck className="w-3 h-3 text-emerald-600" />}
                                      {sMethod === 'Both' ? 'Universal' : sMethod}
