                        shift_name: 'Morning Shift (09:00 - 17:00)',
                        break_title: 'Lunch Break',
                        start_time: '12:00',
                        end_time: '12:45',
                        duration_minutes: 45,
                        days: ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday'],
                        notes: ''
